import { useRef } from 'react';
import { formatPrice, total, type CartItemT, type CartT } from '../services/cart';

type PropsT = {
  cart: CartT;
  onRemove: (productId: string) => void;
};

export default function CartPanel(props: PropsT) {
  const { cart, onRemove } = props;
  const headingRef = useRef<HTMLHeadingElement>(null);

  const handleRemove = (item: CartItemT) => {
    // The row disappears with its last unit, so keep keyboard focus inside the cart.
    if (item.quantity === 1) headingRef.current?.focus();
    onRemove(item.productId);
  };

  return (
    <section aria-labelledby="cart-title">
      <h2 id="cart-title" ref={headingRef} tabIndex={-1}>
        Cart
      </h2>
      {cart.items.length === 0 ? (
        <p>Your cart is empty</p>
      ) : (
        <>
          <ul aria-label="Cart items">
            {cart.items.map((item) => (
              <li key={item.productId}>
                {item.name} × {item.quantity} — {formatPrice(item.price * item.quantity)}{' '}
                <button type="button" onClick={() => handleRemove(item)}>
                  Remove<span className="visually-hidden"> {item.name}</span>
                </button>
              </li>
            ))}
          </ul>
          <p>Total: {formatPrice(total(cart))}</p>
        </>
      )}
    </section>
  );
}
